// Renderiza o passo da régua. Nome: só o primeiro nome.
return $input.all().map(it => {
  const j = it.json; const nome = String(j.nome || '').trim().split(' ')[0] || 'olá';
  const body = String(j.template || '').replace(/\{\{nome\}\}/g, nome).replace(/\{\{escritorio\}\}/g, j.escritorio || 'escritório');
  return { json: { ...j, body } };
});

